CREATE TABLE employee_custodies (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,custody_no VARCHAR(30) NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NULL,issue_date DATE NOT NULL,amount DECIMAL(18,2) NOT NULL,funding_type VARCHAR(10) NOT NULL,funding_account_id BIGINT UNSIGNED NOT NULL,purpose VARCHAR(500) NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',employee_code_snapshot VARCHAR(30) NULL,employee_name_snapshot VARCHAR(190) NULL,project_code_snapshot VARCHAR(30) NULL,project_name_snapshot VARCHAR(190) NULL,funding_account_code_snapshot VARCHAR(6) NULL,funding_account_name_snapshot VARCHAR(190) NULL,issue_journal_entry_id BIGINT UNSIGNED NULL,issued_by BIGINT UNSIGNED NULL,issued_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_employee_custodies_no(custody_no),UNIQUE KEY uq_employee_custodies_issue_journal(issue_journal_entry_id),KEY idx_employee_custodies_employee_status(employee_id,status),KEY idx_employee_custodies_project(project_id),CONSTRAINT fk_employee_custodies_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_funding_account FOREIGN KEY(funding_account_id) REFERENCES accounts(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_journal FOREIGN KEY(issue_journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_issued FOREIGN KEY(issued_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_cancelled FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_employee_custodies_created FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_employee_custodies_amount CHECK(amount>0),CONSTRAINT chk_employee_custodies_funding CHECK(funding_type IN('cash','bank')),CONSTRAINT chk_employee_custodies_status CHECK(status IN('draft','issued','partially_settled','settled','cancelled')),CONSTRAINT chk_employee_custodies_audit CHECK((status='draft' AND issued_by IS NULL AND issued_at IS NULL AND issue_journal_entry_id IS NULL AND cancelled_by IS NULL AND cancelled_at IS NULL) OR(status='cancelled' AND issued_by IS NULL AND issued_at IS NULL AND issue_journal_entry_id IS NULL AND cancelled_by IS NOT NULL AND cancelled_at IS NOT NULL) OR(status IN('issued','partially_settled','settled') AND issued_by IS NOT NULL AND issued_at IS NOT NULL AND issue_journal_entry_id IS NOT NULL AND employee_code_snapshot IS NOT NULL AND employee_name_snapshot IS NOT NULL AND funding_account_code_snapshot IS NOT NULL AND funding_account_name_snapshot IS NOT NULL AND cancelled_by IS NULL AND cancelled_at IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
